const first = $input.first().json;
const body = first.body || {};
const kst = new Date(Date.now() + 9 * 3600 * 1000);
let mode = body.mode;
if (!mode) {
  const mins = kst.getUTCHours() * 60 + kst.getUTCMinutes();
  mode = mins < 570 ? 'weekly' : mins < 720 ? 'start' : 'final';
}
let d = kst;
if (body.today) {
  const s = String(body.today).replace(/\D/g, '');
  d = new Date(Date.UTC(+s.slice(0, 4), +s.slice(4, 6) - 1, +s.slice(6, 8)));
}
const today = d.getUTCFullYear() * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate();
const hhmm = `${String(kst.getUTCHours()).padStart(2, '0')}:${String(kst.getUTCMinutes()).padStart(2, '0')}`;
return [{ json: { mode, today, hhmm, dry: !!body.dry_run, force: !!body.force } }];

const ctx = $('모드 결정').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.name && r.status !== 'ignore' && r.status !== '매도완료');
return [{ json: { ...ctx, mine: rows.map((r) => r.name) } }];

const ctx = $('등록 종목 정리').first().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const html = new TextDecoder('euc-kr').decode(buf);
const strip = (s) => s.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const toDate = (n) => new Date(Date.UTC(Math.floor(n / 10000), (Math.floor(n / 100) % 100) - 1, n % 100));
const toNum = (d) => d.getUTCFullYear() * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate();
const plus = (n, k) => { const d = toDate(n); d.setUTCDate(d.getUTCDate() + k); return toNum(d); };
const today = ctx.today;
const rows = [];
for (const tr of html.match(/<tr[^>]*>[\s\S]*?<\/tr>/g) || []) {
  const link = tr.match(/o=v&amp;no=(\d+)/);
  if (!link) continue;
  const td = (tr.match(/<td[^>]*>[\s\S]*?<\/td>/g) || []).map(strip);
  const m = (td[1] || '').match(/(\d{4})\.(\d{2})\.(\d{2})~(\d{2})\.(\d{2})/);
  if (!m) continue;
  const [, y, sm, sd, em, ed] = m;
  const start = +y * 10000 + +sm * 100 + +sd;
  const end = (+em < +sm ? +y + 1 : +y) * 10000 + +em * 100 + +ed;
  rows.push({ no: link[1], name: td[0], start, end, sm, sd, em, ed, fixed: td[2], hope: td[3], broker: td[5] });
}
let picked = rows.map((r) => ({ ...r, mine: (ctx.mine || []).includes(r.name) }));
picked = picked.filter((r) => r.mine || !/스팩|SPAC/i.test(r.name));
if (ctx.mode === 'weekly') {
  const weekEnd = plus(today, 6);
  picked = picked
    .map((r) => ({ ...r, inWindow: r.end >= today && r.start <= weekEnd }))
    .filter((r) => r.inWindow || (r.mine && r.end >= plus(today, -14)));
} else if (ctx.mode === 'start') {
  picked = picked.filter((r) => r.start === today);
} else {
  picked = picked.filter((r) => r.end === today);
}
picked.sort((a, b) => a.start - b.start);
picked = picked.slice(0, 15);
if (!picked.length) return [{ json: { empty: true, url: 'http://www.38.co.kr/html/fund/index.htm?o=k' } }];
return picked.map((r) => ({ json: { ...r, url: `http://www.38.co.kr/html/fund/?o=v&no=${r.no}` } }));

const ctx = $('등록 종목 정리').first().json;
const cands = $('후보 선정').all().map((i) => i.json);
const mode = ctx.mode;
const today = ctx.today;
const sdata = $getWorkflowStaticData('global');
sdata.grades = sdata.grades || {};
sdata.sent = sdata.sent || {};

const toDate = (n) => new Date(Date.UTC(Math.floor(n / 10000), (Math.floor(n / 100) % 100) - 1, n % 100));
const toNum = (d) => d.getUTCFullYear() * 10000 + (d.getUTCMonth() + 1) * 100 + d.getUTCDate();
const md = (d) => `${String(d.getUTCMonth() + 1).padStart(2, '0')}/${String(d.getUTCDate()).padStart(2, '0')}`;
const addBD = (n, k) => { const d = toDate(n); let c = 0; while (c < k) { d.setUTCDate(d.getUTCDate() + 1); const w = d.getUTCDay(); if (w !== 0 && w !== 6) c++; } return d; };
const todayMd = md(toDate(today));

const chunk = (lines, limit = 185) => {
  const out = []; let cur = '';
  for (const l of lines) {
    if (cur && (cur + '\n' + l).length > limit) { out.push(cur); cur = l; } else cur = cur ? cur + '\n' + l : l;
  }
  if (cur) out.push(cur);
  return out;
};
const link = 'https://www.38.co.kr/html/fund/index.htm?o=k';
const toItems = (msgs) => msgs.map((text) => ({ json: { template_object: JSON.stringify({ object_type: 'text', text, link: { web_url: link, mobile_web_url: link } }) } }));

if (cands.length === 1 && cands[0].empty) {
  return mode === 'weekly' ? toItems([`📅 이번 주 공모주 브리핑 (${todayMd})\n이번 주 청약 예정인 일반 공모주가 없습니다.`]) : [];
}

const num = (s) => (s == null ? null : parseFloat(String(s).replace(/,/g, '')));
const stocks = [];
for (let i = 0; i < cands.length; i++) {
  const c = cands[i];
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const t = new TextDecoder('euc-kr').decode(buf)
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, '')
    .replace(/<[^>]+>/g, '|').replace(/&nbsp;/g, ' ').replace(/[\s|]+/g, ' ');
  const g = (re) => { const m = t.match(re); return m ? m[1] : null; };
  const inst = num(g(/기관경쟁률 ([\d.,]+):1/));
  const confRaw = num(g(/의무보유확약 ([\d.]+) ?%/));
  const conf = inst == null ? null : confRaw;
  const fixed = num(g(/확정공모가 ([\d,]+) 원/)) || num(String(c.fixed).replace(/[^\d,]/g, ''));
  const hm = t.match(/희망공모가액 ([\d,]+) ~ ([\d,]+) 원/);
  const hopeLo = hm ? num(hm[1]) : null; const hopeHi = hm ? num(hm[2]) : null;
  const gen = num(g(/청약경쟁률 ([\d.,]+):1/));
  const lm = t.match(/신규상장일 (\d{4})\.(\d{2})\.(\d{2})/) || t.match(/상장일 (\d{4})\.(\d{2})\.(\d{2})/);
  const listing = lm ? `${lm[2]}/${lm[3]}` : null;
  const listingNum = lm ? +lm[1] * 10000 + +lm[2] * 100 + +lm[3] : null;
  // 평가 (참고 점수, 단일 조건으로 자동 판정하지 않음)
  let score = 0; const pros = []; const risks = [];
  if (inst == null) { risks.push('수요예측 정보 미확인'); }
  else {
    if (inst >= 1000) { score += 2; pros.push('기관 수요 양호'); } else if (inst >= 500) score += 1; else if (inst < 300) { score -= 2; risks.push('기관 수요 부진'); }
  }
  if (conf != null) {
    if (conf >= 20) { score += 2; pros.push('확약률 높음'); } else if (conf >= 10) score += 1; else if (conf < 5) { score -= 1; risks.push('확약률 낮음'); } else risks.push('확약률 다소 낮음');
  } else risks.push('확약률 미확인');
  if (fixed && hopeHi && fixed >= hopeHi) { score += 1; pros.push('공모가 상단 이상'); }
  else if (fixed && hopeLo && fixed < hopeLo) { score -= 1; risks.push('공모가 밴드 하단 미만'); }
  risks.push('상장일 변동성');
  let grade = inst == null ? 'C' : score >= 4 ? 'A' : score >= 2 ? 'B' : score >= 0 ? 'C' : 'D';
  const rm = t.match(/환불일 (\d{4})\.(\d{2})\.(\d{2})/);
  const refund = rm ? `${rm[2]}/${rm[3]}` : `${md(addBD(c.end, 2))}(추정)`;
  stocks.push({ ...c, inst, conf, fixed, hopeLo, hopeHi, gen, listing, listingNum, score, pros, risks, grade, refund });
}
const gi = { A: '☕', B: '☕', C: '🤔', D: '❌' };
const fmtN = (n) => (n == null ? '확인불가' : n.toLocaleString('en-US'));
const priceTxt = (s) => (s.fixed ? `${fmtN(s.fixed)}원` : (s.hopeLo ? `희망 ${fmtN(s.hopeLo)}~${fmtN(s.hopeHi)}원` : '미정'));
const period = (s) => `${s.sm}/${s.sd}~${s.em === s.sm ? '' : s.em + '/'}${s.ed}`;
const instTxt = (s) => (s.inst == null ? '확인불가' : `${s.inst}:1`);
const confTxt = (s) => (s.conf == null ? '확인불가' : `${s.conf}%`);
const verdict = { A: '☕ 최소 수량 청약 고려', B: '☕ 소액(최소수량) 청약 고려', C: '🤔 신중', D: '❌ 패스' };
const finalV = { A: '☕ 청약 고려', B: '☕ 청약 고려', C: '🤔 조건부 청약', D: '❌ 패스' };
const keyOf = (s) => `${mode}|${s.name}|${today}`;

let lines = [];
if (mode === 'weekly') {
  const inWin = stocks.filter((s) => s.inWindow);
  const order = { A: 0, B: 1, C: 2, D: 3 };
  inWin.sort((a, b) => order[a.grade] - order[b.grade] || a.start - b.start);
  lines.push(`📅 이번 주 공모주 브리핑 (${todayMd}, ${inWin.length}건)`);
  if (!inWin.length) lines.push('이번 주 청약 예정인 일반 공모주가 없습니다.');
  for (const s of inWin) {
    if (s.grade === 'A' || s.grade === 'B') {
      lines.push(`${gi[s.grade]}${s.grade} ${s.name} ${period(s)} ${priceTxt(s)} ${s.broker || ''}`.trim());
      lines.push(`  기관 ${instTxt(s)}·확약 ${confTxt(s)}·환불 ${s.refund}·상장 ${s.listing || '미정'}`);
    } else {
      lines.push(`${gi[s.grade]}${s.grade} ${s.name} ${period(s)} ${priceTxt(s)} 기관 ${instTxt(s)}·확약 ${confTxt(s)}`);
    }
    if (!ctx.dry) sdata.grades[s.name] = { grade: s.grade, inst: s.inst, conf: s.conf, date: today };
  }
  const weekEnd = toNum((() => { const d = toDate(today); d.setUTCDate(d.getUTCDate() + 6); return d; })());
  const mineL = stocks.filter((s) => s.mine && s.listingNum && s.listingNum >= today && s.listingNum <= weekEnd);
  for (const s of mineL) lines.push(`📌 내 청약종목 상장: ${s.name} ${s.listing}`);
  lines.push('※ 최소청약·증거금·수수료·유통물량은 증권사/공시 확인(38 미제공). 환불일은 38 기재 기준');
} else {
  const block = [];
  for (const s of stocks) {
    const prev = sdata.grades[s.name];
    const wasGood = prev && (prev.grade === 'A' || prev.grade === 'B');
    const nowGood = s.grade === 'A' || s.grade === 'B';
    if (mode === 'start' && !nowGood) continue;
    if (mode === 'final' && !nowGood && !wasGood) continue;
    if (!ctx.force && sdata.sent[keyOf(s)]) continue;
    const L = [];
    if (mode === 'start') {
      L.push(`${gi[s.grade]} [공모주 청약 시작] ${s.name} · ${s.grade}등급`);
      L.push(`청약 ${period(s)}(마감 통상 16:00, 증권사 확인) · 공모가 ${priceTxt(s)}`);
      L.push(`주간사 ${s.broker || '확인불가'} · 최소청약/증거금/수수료는 증권사 앱 확인`);
      L.push(`기관 ${instTxt(s)} · 확약 ${confTxt(s)} · 유통물량 확인불가`);
      if (s.pros.length) L.push(`✅ ${s.pros.join(', ')}`);
      L.push(`⚠️ ${s.risks.join(', ')}`);
      L.push(`환불 ${s.refund} · 상장 ${s.listing || '미정'}`);
      L.push(`최종 판단: ${verdict[s.grade]}`);
      L.push('※ 조건부 판단이며 수익 보장 아님');
    } else {
      L.push(`🚨 [공모주 최종 청약 판단] ${s.name}`);
      L.push(`마감 통상 16:00(40분 전 확인) · 확인 ${ctx.hhmm}`);
      L.push(`일반청약 경쟁률: ${s.gen != null ? s.gen + ':1(마감 후 확정치)' : '확인불가'}`);
      L.push('예상 균등배정·1주 이상 배정 확률: 확인불가(실시간 수치 미제공)');
      L.push(`기관 ${instTxt(s)} · 확약 ${confTxt(s)} · 현재 ${s.grade}등급`);
      if (prev && prev.grade !== s.grade) {
        const why = [];
        if (prev.inst != null && s.inst != null && prev.inst !== s.inst) why.push(`기관 ${prev.inst}→${s.inst}`);
        if (prev.conf != null && s.conf != null && prev.conf !== s.conf) why.push(`확약 ${prev.conf}→${s.conf}%`);
        L.push(`등급 변경 ${prev.grade}→${s.grade}${why.length ? ' (' + why.join(', ') + ')' : ''}`);
      }
      if (s.pros.length) L.push(`✅ ${s.pros.join(', ')}`);
      L.push(`⚠️ ${s.risks.join(', ')}`);
      L.push(`최종 판단: ${finalV[s.grade]}`);
      L.push('※ 잠정 정보이며 수익 보장 아님');
    }
    block.push(...L);
    if (!ctx.dry) { sdata.sent[keyOf(s)] = true; sdata.grades[s.name] = { grade: s.grade, inst: s.inst, conf: s.conf, date: today }; }
  }
  lines = block;
}
if (!lines.length) return [];
return toItems(chunk(lines));
